// Pega todos os itens recebidos do nó anterior no n8n
const inputItems = $input.all();
const out = [];

for (const item of inputItems) {
    const data = item.json;

    // Verifica se existe o campo 'output' e se ele é uma string JSON
    if (data.output && typeof data.output === 'string') {
        try {
            // Remove quebras de linha escapadas e faz o parse da string JSON
            const parsedOutput = JSON.parse(data.output);

            // Adiciona o item normalizado com as propriedades solicitadas
            out.push({
                json: {
                    ...data, // Mantém os outros dados originais
                    ok: true,
                    to: parsedOutput.to || parsedOutput.to || "", // Pega o destinatário dos campos existentes
                    subject: parsedOutput.subject || "",
                    text_body: parsedOutput.text_body || "",
                    html_body: parsedOutput.html_body || ""
                }
            });
        } catch (e) {
            // Caso ocorra algum erro no parse
            out.push({
                json: {
                    ...data,
                    ok: false,
                    to: data.to || data.email || "",
                    error_parse: "Falha ao converter o output para JSON: " + e.message
                }
            });
        }
    } else {
        // Se o output já for um objeto ou não existir
        out.push({
            json: {
                ...data,
                ok: false,
                to: data.to || data.to || ""
            }
        });
    }
}

return out;

