const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");


  return obj;  

});

return [{ json: {investimentos} }]


return [{ json: { investimentos }}];

// Pega os dados que chegam do nó anterior
const inputData = $input.all()[0].json;

// Garante que temos as listas de clientes e investimentos (ajuste o caminho se necessário, ex: inputData.body)
const clientes =  $input.first().json.body.clientes || [];
const investimentos =  $input.first().json.investimentos || [];

const resultados = [];

// Percorre cada cliente
for (const cliente of clientes) {
  // Filtra todos os investimentos que correspondem ao perfil do cliente
  const produtosCompativeis = investimentos.filter(inv => inv.perfil === cliente.perfil);

  // Monta a lista de produtos em formato de texto para a mensagem
  let listaProdutosTexto = "";
  produtosCompativeis.forEach(prod => {
    listaProdutosTexto += `\n- *\(${prod.produto}* (Rentabilidade: ${prod.rentabilidade}), Mínimo: R$ ${prod.minimo}`;
  });

  // Define um tom personalizado com base no perfil
  let tomPerfil = "";
  if (cliente.perfil === "Conservador") {
    tomPerfil = "priorizando segurança e estabilidade";
  } else if (cliente.perfil === "Moderado") {
    tomPerfil = "buscando um equilíbrio inteligente entre risco e retorno";
  } else {
    tomPerfil = "focado em rentabilidade robusta e exposição a ativos de maior valorização";
  }

  // Cria a mensagem personalizada completa
  const mensagem = `Olá, ${cliente.nome}! Tudo bem? 

Notamos que o seu saldo atual é de \(${cliente.saldo} e seu perfil de investidor é ${cliente.perfil}, ${tomPerfil}.

Com base nisso, separamos as melhores opções de investimento disponíveis para o seu perfil:
${listaProdutosTexto}

Podemos simular uma aplicação em alguma dessas opções para você fazer o seu dinheiro render mais? Estamos à disposição! 🚀`;

  // Adiciona o resultado processado para este cliente
  resultados.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produtos_recomendados: produtosCompativeis,
      mensagem_personalizada: mensagem
    }
  });
}

return resultados;

// Pega todos os itens recebidos do nó anterior no n8n
const inputItems = $input.all();
const out = [];

function parseBRL(valor) {
    if (!valor) return 0;
    const s = String(valor)
        .replace("R$", '')
        .replace(/\./g, '')
        .replace(',', '.')
        .replace(/[^\d.-]/g, '')
        .trim();
    const n = Number(s);
    return Number.isFinite(n) ? n : 0;
}

// Percorre cada item que chegou do nó anterior
for (const item of inputItems) {
    // Extrai o objeto json do item
    const data = item.json;

    // Se os dados estiverem dentro de uma propriedade 'resultados' (caso venham agrupados), 
    // desmembra; senão, trata o próprio item atual.
    const listaResultados = Array.isArray(data.resultados) ? data.resultados : [data];

    for (const c of listaResultados) {
        // Ignora se o objeto estiver vazio
        if (!c || Object.keys(c).length === 0) continue;

        const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

        out.push({ 
            json: {
                email_to: String(c.email || "").trim(),
                nome: String(c.nome || "").trim(),
                perfil: c.perfil || "",
                saldo_texto: c.saldo_texto ?? c.saldo ?? "",
                saldo_num: saldoNum,
                recomendacao: $input.first().json.produtos_recomendados || "",
                motivo: c.motivo || "",
                mensagem_base: c.mensagem_escolhida || c.mensagem || "",
                copy_rules: {
                    idioma: "pt-BR",
                    tom: "amigavel e profissional",
                    tamanho: "curto (4-6 linhas)",
                    evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
                }
            } 
        });
    }
}

return out;
